    // Source: api/requests.js
    class RequestStopped extends Error {}
    class RateLimited extends Error {}

    function requireActiveRequest() {
        if (state.cancelRequested) throw new RequestStopped('Stopped. No further requests will be sent.');
    }

    const { waitForRequestSlot, withRequestSlot } = createHubRequestScheduler({
        state, gapMilliseconds: SETTINGS.requestGapMs, ensureRunning: requireActiveRequest,
        cooldownError: () => new RateLimited('Cooling down after HTTP 429. Start again manually when the timer ends.'),
        onWait: remaining => setStatus(`Waiting ${Math.ceil(remaining / 1000)}s before the next request. Stop is available.`)
    });
    function retryAfterMilliseconds(value) {
        return hubRetryAfterMilliseconds(value, SETTINGS.rateLimitCooldownMs, Date.now(), SETTINGS.rateLimitCooldownMs);
    }

    function requestJson(url, options = {}) {
        return withRequestSlot(() => sendJsonRequest(url, options));
    }

    function requestHub(endpoint, accountToken, payload) {
        assertWhitelisted(accountToken);
        return requestJson(`${SETTINGS.functionsBase}/${endpoint}`, {
            accountToken, body: { accountNumberProxy: accountToken, locale: 'en-US', ...payload }
        });
    }

    // Source: api/transport.js
    // Call only while holding a request slot. Same-offer enrollments share one slot;
    // scan requests and different offers each acquire their own slot.
    async function sendJsonRequest(url, { body, accountToken, source = 'WEB' } = {}) {
        requireActiveRequest();
        if (accountToken) assertWhitelisted(accountToken);
        let timeoutId;
        try {
            const controller = new AbortController();
            timeoutId = setTimeout(() => controller.abort(), SETTINGS.requestTimeoutMs);
            const headers = { Accept: 'application/json', 'ce-source': source, 'one-data-correlation-id': crypto.randomUUID() };
            if (body) headers['Content-Type'] = 'application/json';
            const response = await fetch(url, {
                method: body ? 'POST' : 'GET', credentials: 'include', headers,
                ...(body ? { body: JSON.stringify(body) } : {}), signal: controller.signal
            });
            if (response.status === 429) {
                state.cooldownUntil = Math.max(state.cooldownUntil, Date.now() + retryAfterMilliseconds(response.headers.get('Retry-After')));
                persistCooldown();
                throw new RateLimited('HTTP 429: this run stopped. No automatic retry will be made.');
            }
            if (!response.ok) throw new Error(`HTTP ${response.status}. No automatic retry was made.`);
            try {
                return await response.json();
            } catch {
                throw new Error('The response was not valid JSON; the result is unconfirmed.');
            }
        } catch (error) {
            if (error.name === 'AbortError') throw new Error('Request timed out; the result is unconfirmed. No automatic retry was made.');
            throw error;
        } finally {
            clearTimeout(timeoutId);
        }
    }

    // Source: api/accounts.js
    function normalizeAccounts(accountList) {
        const accounts = new Map();
        function visit(account) {
            if (!account || typeof account !== 'object') return;
            if (typeof account.account_token === 'string' && account.account_token) {
                const cardType = account.product?.description || 'Amex card';
                const cardholder = account.profile?.first_name || '';
                const displayNumber = account.account?.display_account_number || '';
                accounts.set(account.account_token, {
                    token: account.account_token,
                    cardName: [cardType, cardholder, displayNumber ? `(${displayNumber})` : ''].filter(Boolean).join(' · ')
                });
            }
            if (Array.isArray(account.supplementary_accounts)) account.supplementary_accounts.forEach(visit);
        }
        accountList.forEach(visit);
        return [...accounts.values()];
    }

    function accountsFromPage(pageState) {
        for (const moduleName of ['axp-consumer-context-switcher', 'axp-loyalty-root']) {
            const products = pageState?.modules?.[moduleName]?.products?.details?.types?.CARD_PRODUCT?.productsList;
            if (products && typeof products === 'object') {
                const accounts = normalizeAccounts(Object.values(products));
                if (accounts.length) return accounts;
            }
        }
        return Array.isArray(pageState?.accounts) ? normalizeAccounts(pageState.accounts) : [];
    }

    async function detectAccountSnapshot({ forceRefresh = false } = {}) {
        if (!forceRefresh) {
            try {
                const accounts = accountsFromPage(readPageState());
                if (accounts.length) return { accounts, source: 'existing page data; no network request' };
            } catch {
                log('Page card data is unavailable. Trying one account-list request.');
            }
        }
        // One fallback or explicit refresh request; never iterate through cards here.
        const member = await requestJson('https://global.americanexpress.com/api/servicing/v1/member');
        if (!Array.isArray(member?.accounts)) throw new Error('Account-list format was not recognized. Open the Amex Offers page and reload.');
        const accounts = normalizeAccounts(member.accounts);
        if (!accounts.length) throw new Error('No cards were found in this session.');
        return { accounts, source: 'one account-list request' };
    }

    // Source: api/offers.js
    class OfferSchemaError extends Error {}

    function offersInSection(response, sectionName) {
        if (response?.status?.purpose && response.status.purpose !== 'SUCCESS') {
            throw new Error('Offers Hub reported an unsuccessful response.');
        }
        const section = response?.[sectionName];
        const pages = section?.offersList;
        if (!pages || typeof pages !== 'object' || Array.isArray(pages)) {
            throw new OfferSchemaError(`Offers Hub ${sectionName}.offersList was not recognized; this view is incomplete.`);
        }
        if (section.hasMore === true || section.nextPage || response.hasMore === true || response.nextPage) {
            throw new OfferSchemaError('Offers Hub indicated additional server pages; this view is incomplete.');
        }
        const offers = Object.values(pages).flatMap((page) => {
            if (!Array.isArray(page)) throw new OfferSchemaError('An Offers Hub page was not a list.');
            return page;
        });
        if (offers.some((offer) => !offer || typeof offer.offerId !== 'string')) {
            throw new OfferSchemaError('An Offer did not contain a valid identifier.');
        }
        return offers;
    }

    function normalizeHubOffer(offer) {
        const enrollmentStatus = offer.enrollmentDetails?.status;
        const status = enrollmentStatus === 'NOT_ENROLLED' ? 'ELIGIBLE'
            : enrollmentStatus === 'ENROLLED' ? 'ENROLLED' : 'UNKNOWN';
        const name = offer.title || 'Untitled offer';
        const description = offer.shortDescription || '';
        const expiry = offer.expiration?.text || '';
        return {
            id: offer.offerId, name, description, expiry, status,
            type: offer.offerType || 'UNKNOWN',
            enrollable: offer.offerType === 'MERCHANT' && offer.ctaDetails?.ctaType === 'MODAL',
            // Hub IDs may be card-specific. Group only offers with the same visible terms.
            groupKey: JSON.stringify([offer.offerType, name, description, expiry, offer.longDescription || '', offer.terms?.details || '']
                .map((value) => String(value || '').replace(/\s+/g, ' ').trim()))
        };
    }

    async function getAllOffersForAccount(accountToken, onProgress = () => {}) {
        const collected = new Map();
        const viewErrors = [];
        for (const [requestType, sectionName] of [
            ['OFFERSHUB_LANDING', 'recommendedOffers'],
            // The full added view has a different key from the landing/enrollment preview.
            ['ADDEDTOCARD_LANDING', 'addedToCardViewAll']
        ]) {
            requireActiveRequest();
            const response = await requestHub('ReadOffersHubPresentation.web.v1', accountToken, {
                offerPage: 'page1', requestType
            });
            if (response?.accountNumberProxy && response.accountNumberProxy !== accountToken) {
                throw new Error('Offers Hub returned a different card; this scan was stopped.');
            }
            try {
                for (const rawOffer of offersInSection(response, sectionName)) {
                    const offer = normalizeHubOffer(rawOffer);
                    // Prefer the enrolled view if the same offer appears in both lists.
                    if (collected.get(offer.id)?.status !== 'ENROLLED') collected.set(offer.id, offer);
                }
            } catch (error) {
                if (!(error instanceof OfferSchemaError)) throw error;
                viewErrors.push(error.message);
                // Preserve valid results and continue to the other view/card at the same slow pace.
            }
            onProgress([...collected.values()]);
        }
        return { offers: [...collected.values()], viewErrors };
    }

    // Source: api/enrollment-contract.js
    // The existing v3.4 userscript and the 2026-09-10 HAR both use this contract.
    // Keep full-list reads on Offers Hub; changing the list API need not change writes.
    const CARD_ENROLLMENT_ENDPOINT = 'CreateCardAccountOfferEnrollment.v1';

    function enrollmentUserOffset(date) {
        const offsetMinutes = -date.getTimezoneOffset();
        const hours = Math.floor(Math.abs(offsetMinutes) / 60);
        const minutes = Math.abs(offsetMinutes) % 60;
        return `${offsetMinutes >= 0 ? '+' : '-'}${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
    }

    function cardEnrollmentBody(accountToken, offerIdentifier, requestDate = new Date()) {
        return {
            accountNumberProxy: accountToken,
            identifier: offerIdentifier,
            locale: 'en-US',
            requestDateTimeWithOffset: requestDate.toISOString(),
            userOffset: enrollmentUserOffset(requestDate)
        };
    }

    function cardEnrollmentStatus(response, accountToken, offerIdentifier) {
        if (!response || typeof response !== 'object' || Array.isArray(response)) return 'UNCONFIRMED';
        if (response.accountNumberProxy && response.accountNumberProxy !== accountToken) return 'UNCONFIRMED';
        if (response.identifier && response.identifier !== offerIdentifier) return 'UNCONFIRMED';
        if (response.status?.purpose === 'FAILURE' || response.status?.purpose === 'ERROR' || response.isEnrolled === false) return 'FAILED';
        // The original `isEnrolled || true` falsely reported false/missing values as
        // success. Only the literal boolean observed in the successful HAR is valid.
        return response.isEnrolled === true ? 'ENROLLED' : 'UNCONFIRMED';
    }

    function cardEnrollmentEvidence(response) {
        if (response?.isEnrolled === true) return 'isEnrolled=true';
        if (response?.isEnrolled === false) return 'isEnrolled=false';
        return `isEnrolled ${response?.isEnrolled === undefined ? 'missing' : 'has an invalid type'}`;
    }

    // Source: api/enrollment.js
    function enrollOffer(accountToken, offerId) {
        return withRequestSlot(() => sendEnrollmentRequest(accountToken, offerId));
    }

    async function sendEnrollmentRequest(accountToken, offerId) {
        const response = await sendJsonRequest(`${SETTINGS.functionsBase}/${CARD_ENROLLMENT_ENDPOINT}`, {
            accountToken,
            body: cardEnrollmentBody(accountToken, offerId)
        });
        const status = cardEnrollmentStatus(response, accountToken, offerId);
        const cardName = state.accounts.find((account) => account.token === accountToken)?.cardName || 'Selected card';
        log(`${cardName}: ${status} (${cardEnrollmentEvidence(response)}).`);
        return status;
    }

    // Source: workflows/runner.js
    function runAmexAction(actionKind, execute, fail) {
        return runHubActionLifecycle({
            isBusy: () => Boolean(state.busy),
            begin() { state.busy = actionKind; state.cancelRequested = false; render(); },
            execute, fail,
            finish() { state.busy = null; state.cancelRequested = false; render(); }
        });
    }

    // Source: workflows/cards.js
    async function detectCards({ forceRefresh = false } = {}) {
        if (state.busy || (state.detected && !forceRefresh) || Date.now() < state.discoveryRetryAt || Date.now() < state.cooldownUntil) return;
        setStatus(forceRefresh ? 'Refreshing the card list. Your whitelist will be kept.' : 'Detecting card list once. Offers will not be scanned.');
        return runAmexAction('detect', async () => {
            const snapshot = await detectAccountSnapshot({ forceRefresh });
            requireActiveRequest();
            state.accounts = snapshot.accounts;
            state.detected = true;
            // Missing cards keep their saved approval, but only cards in this catalog
            // can be selected for scanning. New card tokens are never opted in.
            persistCardSettings();
            log(`Detected ${state.accounts.length} cards from ${snapshot.source}.`);
            setStatus(forceRefresh
                ? `Refreshed ${state.accounts.length} cards. Existing whitelist selections kept; new cards are unchecked.`
                : `Detected ${state.accounts.length} cards. Add cards to the whitelist, then scan manually.`);
        }, error => {
            state.discoveryRetryAt = Date.now() + SETTINGS.requestGapMs;
            setStatus(`${forceRefresh ? 'Card refresh failed; previous cards and whitelist kept' : 'Card detection failed'}: ${error.message}`);
        });
    }

    function setCardWhitelisted(accountToken, allowed) {
        if (state.busy || !state.detected || !state.accounts.some((account) => account.token === accountToken)) return;
        if (allowed) state.whitelist.add(accountToken);
        else state.whitelist.delete(accountToken);
        persistCardSettings();
        setStatus(`${selectedAccounts().length} cards in whitelist. No scan has been started by this change.`);
        render();
    }

    function cancelRun() {
        if (!state.busy) return;
        state.cancelRequested = true;
        setStatus('Stopping. An already-sent request may finish; no new requests or retries will start.');
        renderControls();
    }

    // Source: workflows/scan-results.js
    async function scanAccountOffers(account) {
        const previousOffers = state.offersByAccount.get(account.token);
        const previousScanTime = state.offerScanTimes.get(account.token) || 0;
        state.scanReports.set(account.token, previousOffers ? 'Scanning · showing saved offers' : 'Scanning');
        renderCards();
        try {
            const result = await getAllOffersForAccount(account.token, (partialOffers) => {
                if (!previousOffers) {
                    state.offersByAccount.set(account.token, partialOffers);
                    state.offerScanTimes.set(account.token, Date.now());
                    state.scanReports.set(account.token, 'Partial — reading both lists');
                    persistOfferResults();
                    renderOffers();
                    renderCards();
                }
            });
            if (result.viewErrors.length && previousOffers) {
                state.scanReports.set(account.token, 'Incomplete · showing previous saved offers');
                state.offerScanTimes.set(account.token, previousScanTime);
                log(`${account.cardName}: refresh incomplete; previous saved offers kept.`);
            } else {
                state.offersByAccount.set(account.token, result.offers);
                state.offerScanTimes.set(account.token, Date.now());
                state.scanReports.set(account.token, result.viewErrors.length ? 'Incomplete' : 'Complete');
            }
            return result;
        } catch (error) {
            state.scanReports.set(account.token, previousOffers ? 'Incomplete · showing previous saved offers'
                : state.offersByAccount.has(account.token) ? 'Incomplete' : 'Not scanned');
            throw error;
        } finally {
            persistOfferResults();
            render();
        }
    }

    // Source: workflows/scan.js
    async function startScan() {
        if (state.busy || !state.detected) return;
        const accounts = selectedAccounts();
        if (!accounts.length) {
            setStatus('Whitelist is empty. Add a card before scanning.');
            return;
        }
        if (Date.now() < state.cooldownUntil) {
            setStatus('Scan is cooling down. Start it manually after the timer ends.');
            return;
        }
        for (const account of accounts) {
            if (!state.offersByAccount.has(account.token)) state.scanReports.set(account.token, 'Pending');
        }
        let completedCards = 0;
        let incompleteCards = 0;
        let attemptedCards = 0;
        return runAmexAction('scan', async () => {
            for (const account of accounts) {
                requireActiveRequest();
                assertWhitelisted(account.token);
                attemptedCards++;
                setStatus(`Scanning ${attemptedCards}/${accounts.length}: ${account.cardName}`);
                const { offers, viewErrors } = await scanAccountOffers(account);
                if (viewErrors.length) {
                    incompleteCards++;
                    viewErrors.forEach((message) => log(`${account.cardName}: ${message}`));
                } else {
                    completedCards++;
                    log(`${account.cardName}: ${offers.length} offers from both full lists.`);
                }
            }
            setStatus(incompleteCards
                ? `Scan finished: ${accounts.length}/${accounts.length} cards attempted; ${completedCards} complete, ${incompleteCards} incomplete. Counts for incomplete cards are partial.`
                : `Scan complete: ${completedCards}/${accounts.length} whitelist cards. Enrollment remains manual.`);
        }, error => {
            setStatus(`${error.message} Completed ${completedCards}/${accounts.length} cards; remaining results are incomplete.`);
            log('The scan stopped. No card was automatically removed from the whitelist.');
        });
    }

    // Source: workflows/enrollment-plan.js
    function groupedOffers({ applyDisplayFilter = true } = {}) {
        const groups = new Map();
        for (const account of selectedAccounts()) {
            for (const offer of state.offersByAccount.get(account.token) || []) {
                if (applyDisplayFilter && state.filter && !`${offer.name} ${offer.description}`.toLowerCase().includes(state.filter)) continue;
                if (!groups.has(offer.groupKey)) groups.set(offer.groupKey, { offer, accounts: [] });
                groups.get(offer.groupKey).accounts.push({ account, offer });
            }
        }
        return [...groups.values()];
    }

    // Every card-offer pair that could be enrolled, before the priority order picks one.
    function enrollmentCandidates(groupKey = null) {
        const seenCardOffers = new Set();
        return groupedOffers({ applyDisplayFilter: false }).filter((group) => !groupKey || group.offer.groupKey === groupKey)
            .flatMap((group) => group.accounts)
            .filter(({ account, offer }) => offer.status === 'ELIGIBLE' && offer.enrollable
                && state.scanReports.get(account.token)?.startsWith('Complete'))
            .filter(({ account, offer }) => {
                const key = JSON.stringify([account.token, offer.groupKey]);
                if (seenCardOffers.has(key)) return false;
                seenCardOffers.add(key);
                return true;
            });
    }

    // The combination template owns cross-card deduplication and target allocation.
    function enrollmentPlan(groupKey = null, { forExecution = false } = {}) {
        const records = forExecution ? offerWorkflow.plan() : offerWorkflow.preview();
        return records.filter(record => !groupKey || record.groupId === groupKey)
            .map(record => ({ account: record.account, offer: record.source }));
    }

    // Source: workflows/enrollment-requests.js
    function updateEnrollmentStatus(account, offer, status) {
        offer.status = status;
        // Duplicate tiles for the same card/offer must not stay eligible after adding.
        for (const equivalent of state.offersByAccount.get(account.token) || []) {
            if (equivalent.groupKey === offer.groupKey) equivalent.status = status;
        }
    }

    // One offer, one card, one request slot. The slot enforces the minimum gap from
    // the previous response, so nothing overlaps and nothing retries on its own.
    function enrollPlannedOffer({ account, offer }) {
        return withRequestSlot(async () => {
            assertWhitelisted(account.token);
            offerWorkflow.assertAction(offer);
            if (offer.status !== 'ELIGIBLE' || !offer.enrollable || !state.scanReports.get(account.token)?.startsWith('Complete')) {
                throw new Error('This offer is no longer eligible on the chosen card. Scan again.');
            }
            setStatus(`Adding ${offer.name} to ${account.cardName}.`);
            const pendingKey = enrollmentStorageKey(account.token, offer.groupKey);
            state.pendingEnrollments.add(pendingKey);
            // A reload cannot tell whether an in-flight enrollment succeeded, so the
            // uncertainty is saved before the request leaves.
            if (!persistOfferResults()) {
                state.pendingEnrollments.delete(pendingKey);
                throw new Error('Could not save pending enrollment state. No enrollment request was sent.');
            }
            try {
                const status = await sendEnrollmentRequest(account.token, offer.id);
                updateEnrollmentStatus(account, offer, status);
                if (status !== 'ENROLLED') throw new Error('Enrollment was not confirmed. Scan again before trying it again.');
            } catch (error) {
                if (offer.status === 'ELIGIBLE' && !(error instanceof RateLimited) && !(error instanceof RequestStopped)) {
                    updateEnrollmentStatus(account, offer, 'UNCONFIRMED');
                }
                log(`${account.cardName}: ${error.message}`);
                throw error;
            } finally {
                state.pendingEnrollments.delete(pendingKey);
                persistOfferResults();
                render();
            }
        });
    }

    // Source: workflows/enrollment.js
    // Adds every planned offer in one unattended run: one request at a time, the
    // minimum gap between them, no retries, and a stop that takes effect immediately.
    async function startEnrollment(groupKey = null) {
        if (!SETTINGS.capabilities.activation || state.busy || Date.now() < state.cooldownUntil) return;
        const plan = enrollmentPlan(groupKey, { forExecution: true });
        if (!plan.length) return;
        state.enrollmentProgress = { total: plan.length, completed: 0 };
        let addedCount = 0;
        return runAmexAction('enroll', async () => {
            log(`Adding ${plan.length} offers one at a time via ${CARD_ENROLLMENT_ENDPOINT}, `
                + `${SETTINGS.requestGapMs / 1000}s apart, across ${new Set(plan.map(({ account }) => account.token)).size} cards.`);
            for (const plannedOffer of plan) {
                await enrollPlannedOffer(plannedOffer);
                addedCount++;
                state.enrollmentProgress.completed = addedCount;
                renderControls();
            }
            setStatus(`Enrollment complete. ${addedCount} offers added.`);
        }, error => {
            setStatus(`${error.message} ${addedCount} offers added.`);
        });
    }

